class TokenAuthenticator(
    private val tokens: TokenStore,
    private val refresh: () -> String?      // blocking refresh call, null on failure
) : Authenticator {

    override fun authenticate(route: Route?, response: Response): Request? {
        if (responseCount(response) > 1) return null           // already retried once: give up

        synchronized(this) {
            val current = tokens.accessToken
            val sent = response.request.header("Authorization")
            val newToken = if (sent != "Bearer $current") current   // someone else refreshed
                           else refresh() ?: return null
            tokens.accessToken = newToken
            return response.request.newBuilder()
                .header("Authorization", "Bearer $newToken")
                .build()
        }
    }

    private fun responseCount(response: Response): Int {
        var count = 1
        var prior = response.priorResponse
        while (prior != null) { count++; prior = prior.priorResponse }
        return count
    }
}

sealed interface ApiResult<out T> {
    data class Success<T>(val value: T) : ApiResult<T>
    data class HttpError(val code: Int, val body: String?) : ApiResult<Nothing>
    data class NetworkError(val cause: IOException) : ApiResult<Nothing>
}

suspend fun <T> safeApiCall(call: suspend () -> T): ApiResult<T> = try {
    ApiResult.Success(call())
} catch (e: CancellationException) {
    throw e                                   // never swallow cancellation
} catch (e: HttpException) {
    ApiResult.HttpError(e.code(), e.response()?.errorBody()?.string())
} catch (e: IOException) {
    ApiResult.NetworkError(e)
}

