class UserApiTest {
    private val server = MockWebServer()

    @Before fun setUp() { server.start() }
    @After fun tearDown() { server.shutdown() }

    @Test
    fun getsUser() = runTest {
        server.enqueue(MockResponse().setResponseCode(200).setBody("""{"id":"1","name":"Ana"}"""))
        val api = buildApi(server.url("/"))

        assertEquals("Ana", api.getUser("1").name)
        assertEquals("/users/1", server.takeRequest().path)     // what was actually sent
    }

    @Test
    fun serverErrorThrows() = runTest {
        server.enqueue(MockResponse().setResponseCode(500))
        assertFailsWith<HttpException> { buildApi(server.url("/")).getUser("1") }
    }
}
